  'settings.access.phrase.howStep3': '完了です。各インスタンスが互いの「インスタンス」に現れ、どちらからでもどちらも操作できます。リレーを入れておけば、ネットワークの外からも届きます。',
  'settings.access.phrase.howWhat': '言葉は住所ではなく秘密です。各インスタンスはそこから鍵を二つ作ります。ひとつは相手を見つけるため、もうひとつは暗号化のためです。\n\n見つけ合うために、各インスタンスは自分からインターネット上の同じ待ち合わせ場所へ呼びかけます。同じ鍵を示した相手同士がつながります。だからどのインスタンスも外部から到達できる必要はありません。\n\n待ち合わせ場所は中身を読めません。あなたの言葉を見ることはなく、そこを通るものはすべて二つ目の鍵で暗号化されています。',
