  'settings.torrents.privateNote': 'プライベートトレントでは、ここでの設定にかかわらず、メタデータが分かった時点で両方が自動的にオフになります。アップロードした .torrent ファイルならすぐに、マグネットリンクならそのメタデータがスウォームから届いた時点でオフになります。ほとんどのプライベートトラッカーは、どちらかを使ったアカウントを BAN します。',
