  'torrent.tree.add': 'コレクターに追加',

  'settings.torrents.engineLimits': '目標シードレシオと目標シード時間は、このエンジンが開始するすべてのトレントに効きます。ポートが効くのは、このインスタンスの前回の再起動以降に最初に開始したトレントだけです。エンジンは自分のトレントクライアントを一度だけ作り、作り直すことがないからです。あとでポートを変更しても正しく保存され、次の再起動から有効になります。アップロード制限は今のところ保存と検証だけで、エンジンにはまだ実行中のダウンロードに適用する手段がありません。通常のトレントでは、下の DHT と PEX もまだ効きません。このインスタンス自身の既定値が実行中のダウンロードに届かないため、ここでの設定に関係なく、トレントは両方オンのままシードします。プライベートトレントは別の扱いで、下の「ピア探索」の (i) で説明しています。下のマッピングのボタンはそれとは関係なく動作し、トレントがまだそのポートで待ち受けていなくても、上に入力したポート番号を転送するようルーターに依頼します。',
  'onboarding.step': 'ステップ {n}/{total}',
