  'onboarding.finish': '完了',
  'onboarding.welcome.title': 'KnightLoaderへようこそ',
  'onboarding.welcome.body': 'KnightLoader はセルフホスト型のダウンロードマネージャーです。リンクを貼り付けるかドロップすると、それに合ったバックエンドが取得します。通常のファイルリンクには組み込みエンジン、メディアページには yt-dlp、すでに料金を払っているホスターには debrid サービス、それ以外にはヘッドレスの JDownloader が使われます。この短いツアーでは、始める前に確認しておきたい設定を一つだけ紹介します。',
  'onboarding.welcome.langLabel': 'インターフェースの言語',
