  'onboarding.accounts.title': 'プレミアムホスター、必要なときに',
  'onboarding.accounts.body': 'キューはアカウントがなくても動作します。すでに料金を払っているホスターや debrid サービスで最高速度を使いたくなったら、アカウントでそのログインを追加してください。今は何も設定する必要はありません。',
