  'settings.feeds.seededHint': '新しい購読の初回の取得は、その時点でフィードに載っているものをすべて記録し、そのどれも取り込みません。配信元の過去の一覧が一度に降ってくることのないようにするためです。取り込まれるのは、そのあとに現れたものだけです。',
  'settings.feeds.remembered': '{n} 件のエントリーを記憶',
