  'settings.headerProfiles.hint': 'サイトによっては、ログイン済みのブラウザーにしか、あるいは自分たちのページから来た呼び出しにしかファイルを渡しません。プロファイルは、ちょうど 1 つのサイトのためのヘッダーを、あなたのアカウントの認証情報と同じように暗号化して保存し、KnightLoader はそのサイトからのダウンロードのたびに一緒に送ります。',
  'settings.headerProfiles.empty': 'ヘッダープロファイルはまだありません。',
