  'settings.rules.action.category': 'カテゴリー',
  'settings.rules.action.categoryHint': '一致したリンクを、このページの下のほうにある「カテゴリー」一覧の引き出しのひとつへ収めます。引き出しは自分のフォルダー、キューでの位置、展開のスイッチ、ファイルがすでにある場合の規則を一緒に連れてきます。「変更なし」のままなら、どのルールもこれについて何も言わず、リンクはどこにも収められません。このルールが保存先フォルダーも指定している場合は、そのフォルダーが勝ち、残りはすべて引き出しが受け持ちます。すでに削除された引き出しを指定すると、保存のときに拒否されます。存在しない引き出しを指すルールは、一致したどのリンクに対しても、何も言わずにまったく何もしないからです。',
  'settings.rules.action.categoryNone': 'カテゴリーはまだありません。まずこのページの下のほうにある「カテゴリー」で 1 つ作ってください。そうしないと、このルールは存在しない引き出しへリンクを収めることになります。',
