  'disk.title': '書き込み先フォルダー',
  'disk.hint': 'ダウンロードの保存先になりうる各フォルダーの空き容量と使用量、そしてキューがそれぞれにまだ書き込む量です。数値はディスクの制限を確認するのと同じ呼び出しから取得しており、古くても数秒前のものです。空き容量と使用量を足してもボリュームのサイズになるとは限りません。ファイルシステムはシステム用に一部を確保しており、ユーザーごとのクォータがあると、このインスタンスが使える量はボリュームの実際の空きより少なくなることがあります。同じディスク上の二つのフォルダーはどちらもそのディスクを表示するので、行どうしを足さないでください。',
  'disk.free': '空き',
  'disk.used': '使用済み',
  'disk.size': 'ボリュームのサイズ',
  'disk.queued': 'これから書き込む分',
  'disk.queuedHint': 'まだ残っているダウンロードが、このフォルダーへ書き込む量です。ホスターが伝えたサイズから、すでに届いた分を引いたものです。ホスターがサイズを言わないダウンロードはここでは 0 として数えるので、この数字は下限であって約束ではありません。ダウンロードが何件も並んでいるのに 0 バイトと出ることがあるのは、そのためです。オフにしたダウンロードは入りません。一覧の下のカウンターと同じ規則です。すでに走っているダウンロードは、たいてい開始の時点でディスク上に場所を取ってあるので、そのバイトは隣の空きの数字からすでに引かれています。この数字の上に足されるわけではありません。',
  'disk.tasks': '{n} 件のダウンロード',
  'disk.unknown': 'このシステムは空き容量を報告しません',
  'disk.unknownHint': 'すべてのカーネルでボリュームの残り容量を問い合わせられるわけではなく、このビルドには、いま動いているカーネル向けの呼び出しがありません。答えが得られない場合は何も止めず、ディスクの制限が設定されていないかのようにダウンロードが始まります。この行は、本当にいっぱいのディスクと区別できるようにするためのものです。',
  'disk.missing': 'まだ作られていません',
  'disk.missingHint': 'このフォルダーは、最初のファイルを書き込むものが作ります。だからまだありません。数字が表しているのは {path}、実在する中でいちばん近い上のフォルダーで、それはダウンロードが着地するボリュームの上にあります。',
  'disk.measured': '{path} で測定',
  'disk.elsewhereHint': 'フォルダー自体は測れなかったので、測れた中でいちばん近い上のフォルダーの値です。マウントが上がっていなければ、ダウンロードの行き先とはまったく別のディスクということもあります。数字から何かを読み取る前に、パスを確かめてください。',
  'disk.sampled': '{n} 秒前に読み取り',
  'disk.tight': 'キューの分が収まりません',
  'disk.tightHint': 'このフォルダーに書き込む予定の量が、ボリュームの空きを超えています。この行だけでは何も止まりません。止めるのは順番が回ってきたダウンロードを 1 件ずつで、その判断は設定のダウンロードページにある数字が行います。誰もサイズを知らないダウンロードは、ここにはまったく数えられていません。',
  'disk.truncated': 'すべてのフォルダーが載っているわけではありません',
