  'settings.volume.title': 'ダウンロード量の上限',
  'settings.volume.titleHint': 'このインスタンスが完了したダウンロードの量を、自分で決めた上限に対して期間ごとに数えます。数えるのは、完了したダウンロードについてホスターが伝えたサイズです。サイズが示されないまま完了したものは 0 として数え、トレントがアップロードした分はまったく数えません。これはダウンロードの集計であって、回線の測定ではありません。ルーターが実際に動かしたバイトは、ここからは誰にも見えません。',
  'settings.volume.cap': '期間ごとの上限（GB）',
  'settings.volume.capHint': '0 は上限なしです。カウンターは動き続け、何も止められません。ここでのギガバイトは、プロバイダーが容量を示すときと同じ 10 進です。500 GB は 500 000 000 000 バイトであって、465 GiB ではありません。このページの上のほうにあるディスクのしきい値は 2 進の GiB で、別の問いのための別の単位です。',
  'settings.volume.resetDay': 'カウンターが 0 に戻る日',
  'settings.volume.resetDayHint': 'カウンターが月のうちどの日に 0 へ戻るかです。ふつうは容量が新しく割り当てられる日にします。選んだ日より短い月では、代わりにその月の最終日に戻り、翌月へずれ込むことはありません。数えるのはサーバーの時計で、ブラウザーの時計ではありません。キューを止めるのはサーバーだからです。',
  'settings.volume.action': '上限に達したときの動作',
  'settings.volume.actionHint': 'どれを選んでも、すでに実行中の転送が中断されることはありません。ファイルの途中で止めると、すでに使ったバイトが無駄になるからです。「知らせるだけ」は何も変えず、カウンターだけの機能になります。「新しいダウンロードを始めない」は実行中のものを最後まで終わらせ、カウンターがリセットされるまでキューを止めます。待っている行にはその旨が表示されます。「すべて速度を落とす」は、下の速度でキューを動かし続けます。',
  'settings.volume.actionReport': '知らせるだけ',
