  'settings.volume.throttleHint': 'その期間の残りに適用される速度です。ほかの制限の代わりではなく、それらと並ぶ上限なので、より低い値を求める夜間のウィンドウや静かに動かすスイッチのほうが引き続き勝ちます。ここでの 0 はまったく制限しないという意味になり、上限がないのと同じです。意味のあるいちばん小さい数字は 1 です。',
