  'settings.transfer.group.look': '外観',
  'settings.transfer.group.other': 'その他すべて',
  'settings.mediahook.title': 'メディアライブラリーの呼び出し',
  'settings.mediahook.hint': 'パッケージの最後のファイルが届き、所定の場所へ移されたあとに、KnightLoader が一度だけ呼び出すアドレスです。Jellyfin や Plex でライブラリーを読み直させるためのものですが、この欄はそのどちらのことも知りません。あなたが入力したアドレスを、あなたが選んだメソッドで呼び出し、ヘッダーを 1 つ指定すればそれを付け加えるだけです。ヘッダーの値は、アカウントのログインと同じ暗号化された保管庫に封をして置かれ、このページに戻ってくることはありません。アドレスを登録して、ルールとカテゴリーのページの引き出しでそれを選ぶまでは、何も呼び出されません。パッケージ名のないダウンロードが呼び出しを起こすことは決してありません。その最後のファイルであるべきパッケージが存在しないからです。サーバーの再起動中に完了したパッケージについても呼び出されません。最初の巡回は、すでに完了しているものを書き留めるだけで、知らせはしないからです。',
  'settings.mediahook.empty': 'アドレスはまだ登録されていません。',
  'settings.mediahook.emptyHint': 'メディアサーバーが新しいファイルに自分で気づかないなら、登録する価値があります。',
  'settings.mediahook.add': 'アドレスを追加',
  'settings.mediahook.name': '名前',
  'settings.mediahook.nameHint': 'ルールとカテゴリーのページの引き出しで、このアドレスを選ぶときの名前です。使えるのは英字、数字と - _ または . だけです。あとから変えることはできません。引き出しはこの名前でアドレスを指しているからです。',
  'settings.mediahook.url': 'アドレス',
  'settings.mediahook.urlHint': '呼び出される完全なアドレスです。http か https で、ホストとポートも含めて書きます。保存する前に一度読み直してください。ここに書いたものが、このマシンから呼び出されます。アドレス自体は settings.json に平文で保存され、診断パッケージにも入っていきます。だからトークンは、アドレスのクエリ部分ではなく、下のヘッダーに入れてください。',
  'settings.mediahook.method': 'メソッド',
  'settings.mediahook.methodHint': 'GET か POST。POST は本文なしで送られます。Jellyfin は POST を、Plex は GET を求めます。迷ったら、テスト呼び出しが相手のどちらを受け付けるか教えてくれます。',
  'settings.mediahook.headerName': 'ヘッダーの名前',
  'settings.mediahook.headerNameHint': '呼び出しと一緒に送られる唯一のヘッダーです。Jellyfin なら例えば X-Emby-Token。空のままにすれば、追加のヘッダーは送られません。',
  'settings.mediahook.headerValue': 'ヘッダーの値',
  'settings.mediahook.headerValueHint': 'そのヘッダーに入るトークンです。アカウントのログインと同じ暗号化された保管庫に封をして置かれ、settings.json に書かれることも、このページに送り返されることもありません。',
  'settings.mediahook.valueStored': '保存済み',
  'settings.mediahook.valueStoredHint': '値はこのインスタンスに残ります。欄をそのままにすれば保たれ、新しい値を入力すれば置き換わります。欄を空にすると、値は消えます。',
  'settings.mediahook.goesTo': '呼び出しは {host} へ行きます',
  'settings.mediahook.goesToForeign': 'このアドレスはあなた自身のネットワークにはありません。呼び出しはこのマシンを出ていき、ヘッダーも一緒に出ていきます。',
  'settings.mediahook.wait': '呼び出す前の待ち時間',
  'settings.mediahook.waitHint': 'パッケージが完了したあと、このアドレスをどれだけそっとしておくかです。20 個のパッケージが同時に完了しても、20 回ではなく 1 回の呼び出しで済みます。ライブラリーのスキャンはメディアサーバーに本当の仕事をさせますが、1 分遅れて届いてもあなたには何の損もありません。0 にすると、パッケージのファイルが所定の場所に収まった時点で、ほかを待たずに呼び出しが出ていきます。',
  'settings.mediahook.waitImmediate': 'パッケージが 1 つ出来上がり次第、ほかを待たずに呼び出しが出ていきます。',
  'settings.mediahook.error.nameInvalid': '名前に使えるのは英数字と - _ . だけで、最大 64 文字です。',
  'settings.mediahook.save': 'アドレスを保存',
  'settings.mediahook.delete': 'アドレスを削除',
  'settings.mediahook.deleteConfirm': '{name} を削除しますか? 保存されたヘッダーの値も一緒に消え、このページから戻すことはできません。',
  'settings.mediahook.deleteInUse': '{name} はまだ {n} 件の引き出しで選ばれています。まずそれらを「呼び出さない」にしてから削除してください。',
  'settings.mediahook.usedBy': '{n} 件の引き出しで選ばれています',
