  'settings.health.parts': '構成要素',
  'settings.health.partsHint': 'アプリの中で単独で故障しうる部分ごとに1行あります。このインスタンスで一度も設定していない部分は、不具合として数えられるのではなく、そのように表示されます。このビルドが状態を問い合わせられない部分も同じです。行を読んでも何も変わりません。動いていないと表示されている部分は、すでにしばらく前から失敗していて、ここはそれに気づく場所にすぎません。',
