  'health.remedy.store.failed': 'データベースが応答しませんでした。ダウンロードは走り続けますが、それについては何も書き留められなくなっているので、再起動すればそれ以降に変わったものはすべて失われます。データフォルダーがまだマウントされていて、まだ書き込めるかを確かめてください。',
  'health.remedy.jd.unreachable': 'KL_JD が挙げているアドレスに、このインスタンスはいま届きません。JDownloader のコンテナが動いているか、その API ポートがここから応答するかを確かめてください。JDownloader にしか取れないリンクは、そのあいだキューに残ります。失敗したわけではありません。',
  'health.remedy.jd.notWired': 'JDownloader はまた応答していますが、このプロセスは起動時にバックエンドをつないでいて、そのときはまだ無かったのです。取り込ませるには KnightLoader を再起動してください。',
  'health.remedy.ytdlp.missing': 'このプロセスの起動時に yt-dlp が見つかりませんでした（KL_YTDLP か、PATH 上の "yt-dlp"）。メディアページはそのとき、複数の品質に展開される代わりに、サイト自身のエラーで失敗します。見つけさせるには再起動が必要です。',
  'health.remedy.disk.low': '保存先フォルダーの 1 つが、ダウンロードのページで設定した下限を割っています。また空きができるまで、または下限を下げるまで、そこでは新しいものが始まりません。すでに走っているものは、この下限では止まりません。',
  'health.remedy.disk.elsewhere': 'フォルダーが 1 つ存在しないので、数値はその上にある直近のフォルダーを表しています。マウントが上がっていなければ、それはまったく別のディスクです。数字を信じる前に、パスを見てください。',
