  'health.remedy.accounts.invalid': 'ホスターのアカウントが少なくとも 1 つ拒否されました。直るのは新しいキーか、更新した契約です。待っても直りません。',
  'health.remedy.feeds.failing': '購読が少なくとも 1 つ、前回の取得に失敗しました。どれがなぜ失敗したかは、ダウンロードのページのフィードの横と、診断ページのログ行にあります。',
  'health.remedy.relay.down': 'リレーのアドレスが保存されていて、接続が上がっていません。このインスタンスは自分で再試行を続け、手元のものはいつもどおり動きます。外から届かないだけです。',
