  'settings.health.scrapeHint': '同じ数値をそのままのテキストで返す 2 つ目のアドレスを開きます。形式は Prometheus と、それにならって作られた道具が読むものです。取りに来られるだけで、こちらから送ることはありません。あなた自身の監視がここへ来て求めないかぎり、このマシンから出ていくものはありません。オフのあいだ、そのアドレスはそもそも存在せず、このアプリが持たないほかのアドレスと同じように 404 を返します。パスワードを掛けたインスタンスでは、取得にあなたの API トークンが 1 つ必要で、どの収集ツールにも送らせることができます。収集ツールは Origin ヘッダーを送らないので通り、別のアドレスで開いたブラウザーのタブは送るので、このインスタンス自身のアドレスと一致しなければ拒まれます。テキストには保存先フォルダーのパスが入っているので、フォルダー名そのものを渡してよい相手にだけ渡してください。',
