  'settings.owner.envHow': '別のアカウントで動かしたいときは、起動コマンドでそれを指定してください: --user <uid>:<gid>。Unraid ではこれを Extra Parameters に書き、効かせるにはコンテナを作り直す必要があります。',
  'settings.owner.desktopNote': 'デスクトップアプリはあなた自身のアカウントで動きます。PUID、PGID、UMASK はコンテナの設定で、ここでは何もしません。',
