  'settings.owner.checkTitle': 'フォルダーの確認',
  'settings.owner.checkHint': 'ここでは本当に、それぞれのフォルダーにファイルを 1 つとサブフォルダーを 1 つ書き込み、その両方が誰のもので、ほかに誰が読めるかを読み返し、両方とも消します。これは計算で出すのではなく、実際に測るしかありません。共有フォルダーは独自の権限ルールを持ち込むことがあり、set-group-id が付いたフォルダーは、このプロセスが持つものとは別のグループを渡すからです。この確認は、変更したフォルダーを保存したあとに自分から走り、ボタンを押したときにはいつでも走ります。',
