  'settings.owner.v.ownerMismatch': 'ここに着地するファイルは {fileOwner} のものですが、フォルダーは {dirOwner} のものです。読むだけならたいてい通ります。別のアカウントからの名前の変更、移動、削除は通りません。そして、フォルダーが自分の中身を所有しているものと考える相手は、これらのファイルをよそのものとして扱います。',
