  'settings.selftest.accounts.advice.error': 'プロバイダーは、新しいキーでも待つことでも解けないものを挙げています。たとえば、あなたのアドレスに対する遮断です。',
  'settings.selftest.accounts.readOnlyHint': 'この確認は振り分けを何も変えません。ここで失敗したログインは報告されるだけで、休ませはしません。回線が落ちているあいだに走った自己診断が、この先 15 分すべてのアカウントを止めてしまってはいけないからです。',
