  'settings.diagnostics.check.java': 'Java',
  'settings.diagnostics.check.ytdlp': 'yt-dlp',
  'settings.diagnostics.check.ffmpeg': 'ffmpeg',
  'settings.diagnostics.check.ffprobe': 'ffprobe',
  'settings.diagnostics.check.clock': 'タイムゾーンとローカル時刻',
  'settings.diagnostics.role.downloads': '保存先フォルダー',
  'settings.diagnostics.role.work': '作業フォルダー',
  'settings.diagnostics.role.category': 'カテゴリーのフォルダー',
  'settings.diagnostics.role.extract': '展開フォルダー',
  'settings.diagnostics.role.extractMove': '展開したものの移動先フォルダー',
  'settings.diagnostics.role.watch': '監視フォルダー',
  'settings.diagnostics.fix.missing': 'そのフォルダーはありません。その上にある、実在するいちばん近いフォルダーは {measured} です。共有フォルダーをマウントするマシンでは、たいてい共有がマウントされていないことを意味します。だからこの確認ではフォルダーを作りません。マウントがない状態でその下にフォルダーを作ると、そこにダウンロードが入ってしまい、次のコンテナ更新で消えてしまうからです。',
  'settings.diagnostics.fix.denied': 'そのフォルダーはありますが、このインスタンスは中に書き込めません。コンテナの中で KnightLoader は uid 1000 として動くので、フォルダーはそのユーザーのものか、そのユーザーが属するグループのものである必要があります。',
  'settings.diagnostics.fix.readonly': 'このフォルダーの下のファイルシステムは、読み取り専用でマウントされています。これはこのインスタンスには変えられません。マウントのほうを変える必要があります。',
  'settings.diagnostics.fix.full': 'このフォルダーが載っているボリュームに、空きが残っていません。',
