  'settings.diagnostics.fix.notADir': 'このパスにあるのはファイルであって、フォルダーではありません。',
  'settings.diagnostics.fix.timeout': 'そのフォルダーは時間内に応答しなかったので、そのままにしました。サーバーが止まっている共有はまさにこう振る舞い、消えてしまったネットワークの上にある共有も同じです。',
  'settings.diagnostics.fix.dataDenied': 'これは、このインスタンスが欠かせないただ一つのフォルダーです。データベース、設定、暗号化されたアカウントの保管庫が、すべてここにあります。ダウンロードはいまのところ走り続け、次に保存したものは失われます。',
  'settings.diagnostics.fix.javaMissing': 'Java が見つかりませんでした。コンテナイメージは 1 つ同梱しています。デスクトップのインストールでは、同梱のランタイムか PATH 上のものを使います。Java がないと専用の JDownloader が起動しないので、暗号化されたコンテナのリンク (.dlc、.ccf、.rsdf) はそもそも開けません。JAVA_HOME を設定するか、よそで動いている JDownloader を KL_JD で指してください。',
  'settings.diagnostics.fix.javaNotNeeded': 'このインスタンスは自分の Java プロセスを起動しません。KL_JD がよそで動いている JDownloader を指しているか、専用のほうが KL_PROVISION_JD=0 で切られているかのどちらかです。',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp が見つかりませんでした（KL_YTDLP か、PATH 上の "yt-dlp"）。メディアページはそのとき、ダウンロードされる代わりにサイト自身のエラーで失敗します。',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg が見つかりませんでした。yt-dlp は、ほとんどのサイトが別々に渡してくる映像と音声のストリームをつなぐのに、これを必要とします。ですからダウンロードは片方で止まるか、音のないものが返ってきます。',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe が見つかりませんでした。これを使うのは、できあがった動画の長さの確認だけです。ほかはすべてこれなしで動きます。',
  'settings.diagnostics.fix.notRunnable': '{subject} で見つかりましたが、実行できませんでした: {error}',
  'settings.diagnostics.fix.appearedLate': 'いまは動いていますが、このインスタンスの起動時にはありませんでした。ですからまだ何も振り分けられていません。取り込ませるには再起動してください。',
  'settings.diagnostics.fix.utcFallback': 'TZ は {subject} になっていますが、このインスタンスはそのゾーンを読み込めず、どこにも言わないまま UTC に戻りました。これが直るまで、スケジュールの枠はすべて UTC で走ります。ゾーンの一覧と照らして綴りを確かめ（「Europe/Berlin」）、そもそもイメージにゾーンのデータベースがあるかどうかも確かめてください。',
  'settings.diagnostics.fix.noZoneDatabase': 'このシステムにはゾーンのデータベースがないので、時刻は夏時間の切り替えをまったく持たないまま読まれます。夜の枠は夏のあいだもずっと冬の時刻のままで、そうなっても誰も知らせません。',
  'settings.diagnostics.fix.tzUnset': 'TZ が設定されておらず、ローカル時刻も見つからなかったため、このインスタンスは UTC で動いています。それでも動作しますが、23:00 と書いたスケジュールのウィンドウは、あなたのいる場所の 23:00 ではなく UTC の 23:00 を意味します。',
