  'settings.resolvers.toolsYtdlpMissingHint': 'yt-dlp がないと、メディアのバックエンドはそもそも存在しません。動画ページへのリンクは、ダウンロードされる代わりにサイト自身のエラーで拒否されます。コンテナではイメージの yt-dlp パッケージから来ます。デスクトップでは自分でインストールして、PATH に置くか KL_YTDLP をそこへ向けます。どちらも取れないときは、下のボタンが自分でコピーを 1 つ取ってきます。',
  'settings.resolvers.toolsFfmpegMissingHint': 'ffmpeg がないと、yt-dlp は、ほとんどのサイトが別々に渡してくる映像と音声のトラックをつなげません。ですからダウンロードは音のない映像トラックとして着地するか、そのまま失敗します。ffprobe がないと、このページの上のほうにある「完成したファイルを測る」は何も測らず、それについて何も言いません。コンテナではどちらもイメージが入れる ffmpeg パッケージから来ます。デスクトップでは自分でインストールして PATH に置きます。',
  'settings.resolvers.toolsShadowed': 'KnightLoader 自身のコピーが動いています。これがあるあいだ、KL_YTDLP と PATH は起動されません。代わりに使われるとしたら {path} で、それは {version} と名乗ります。',
  'settings.resolvers.toolsShadowedOlder': '注意: KnightLoader が取ってきたコピー ({current}) は、このマシンにもともとあるもの ({system}、場所は {path}) より古いです。コンテナの更新は新しい yt-dlp を連れてきますが、あなた自身のコピーはそれに付いていきません。新しいものを取ってくるか、システムのコピーに戻ってください。',
  'settings.resolvers.toolsManagedBroken': '{path} に取ってきたコピーが登録されていて、それが起動しません。代わりに動いているのは、上に出ている代替です。もう一度取ってくるか、システムのコピーに戻ってください。',
  'settings.resolvers.toolsActions': 'yt-dlp を最新に保つ',
  'settings.resolvers.toolsActionsHint': '「取ってくる」は yt-dlp を github.com からダウンロードし、同じリリースで公開されている SHA2-256SUMS ファイルと突き合わせ、このマシンでそもそも動くかを見るために一度起動し、そのうえで初めてあなたのデータの隣、KnightLoader がそれを起動する場所に置きます。この最後の一歩までは、すでに持っていたコピーがそのまま動き続け、システム自身の yt-dlp には一切触れません。',
